<?php if (!$data['product']): ?><section class="page-intro shell"><span class="eyebrow">404 — NOT FOUND</span><h1>পণ্যটি খুঁজে পাওয়া যায়নি।</h1><a class="button button-green" href="/shop">দোকানে ফিরে যান</a></section><?php else: $product = $data['product']; $images = $product['images'] ?: [['image_url' => asset('category-tech.jpg'), 'alt_text' => $product['name']]]; ?><section class="product-detail shell"><div class="detail-gallery"><div class="detail-main-image"><img src="<?= e($images[0]['image_url']) ?>" alt="<?= e($images[0]['alt_text'] ?: $product['name']) ?>"></div><?php if (count($images) > 1): ?><div class="detail-thumbnails"><?php foreach (array_slice($images, 1, 4) as $image): ?><img src="<?= e($image['image_url']) ?>" alt="<?= e($image['alt_text'] ?: $product['name']) ?>" loading="lazy"><?php endforeach; ?></div><?php endif; ?></div><div class="detail-copy"><span class="eyebrow"><?= e($product['category_name'] ?? 'ALLSTORE PICK') ?></span><h1><?= e($product['name']) ?></h1><?php if (!empty($product['brand_name'])): ?><p class="detail-brand"><?= e($product['brand_name']) ?></p><?php endif; ?><p class="detail-price"><?= e(format_price((float) $product['price'])) ?><?php if (!empty($product['compare_at_price']) && (float) $product['compare_at_price'] > (float) $product['price']): ?><del><?= e(format_price((float) $product['compare_at_price'])) ?></del><?php endif; ?></p><p class="stock-status"><?= (int) $product['stock_quantity'] > 0 ? 'মজুতে আছে' : 'এই মুহূর্তে মজুতে নেই' ?></p><p class="detail-description"><?= nl2br(e($product['description'] ?? $product['short_description'] ?? '')) ?></p><?php if ((int) $product['stock_quantity'] > 0): ?><form action="/cart/add" method="post" class="detail-form"><?= csrf_field() ?><input type="hidden" name="product_id" value="<?= e($product['id']) ?>"><label for="quantity">পরিমাণ</label><input id="quantity" type="number" name="quantity" value="1" min="1" max="<?= min(20, (int) $product['stock_quantity']) ?>"><button class="button button-green" type="submit">ব্যাগে যোগ করুন <span aria-hidden="true">→</span></button></form><?php endif; ?><p class="detail-note">মূল্য ও মজুত সার্ভার থেকে যাচাই করা হয়। Checkout এবং payment flow এখনো চালু করা হয়নি।</p></div></section><?php endif; ?>
